INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-112',unit_id,'quiz-topic-neuro-ap1','Que sutura divide o palato duro em metades direita e esquerda?',NULL,'O palato ósseo situado no interior da arcada alveolar superior é formado anteriormente pelas apófises palatinas das maxilas e posteriormente pelas lâminas horizontais dos palatinos, que se encontram num sistema cruciforme de suturas. A <strong>sutura palatina mediana</strong> percorre o palato no sentido anteroposterior e divide-o em metades direita e esquerda; continua-se anteriormente com a sutura intermaxilar entre os incisivos centrais superiores. As suturas palatinas transversas ou palatomaxilares atravessam o palato entre as maxilas e os palatinos.<p><small>Gray’s Anatomy, 42.ª ed., pp. 563–564.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-112-answer','quiz-neuro-ap1-112','Sutura palatina mediana',1,1);
