INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-116-incorrect','quiz-neuro-ap1-116','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-117',unit_id,'quiz-topic-neuro-ap1','Que buraco se situa junto do bordo lateral do palato, ao nível da sutura palatina transversa?',NULL,'Quando existem buracos incisivos medianos, o nervo nasopalatino esquerdo atravessa habitualmente o buraco anterior e o direito o posterior. O <strong>buraco palatino maior</strong> situa-se próximo do bordo lateral do palato ao nível da sutura palatina transversa; dele parte anteriormente um sulco vascular mais profundo atrás e mais superficial à frente. Os buracos palatinos menores, habitualmente dois, situam-se posteriormente ao buraco palatino maior e atravessam a apófise piramidal do palatino, encaixada entre as extremidades inferiores das lâminas pterigóideas medial e lateral.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-117-answer','quiz-neuro-ap1-117','Buraco palatino maior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-117-incorrect','quiz-neuro-ap1-117','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-118',unit_id,'quiz-topic-neuro-ap1','Que buracos se situam posteriormente ao buraco palatino maior?',NULL,'O buraco palatino maior situa-se próximo do bordo lateral do palato ao nível da sutura palatina transversa; dele parte anteriormente um sulco vascular mais profundo atrás e mais superficial à frente. Os <strong>buracos palatinos menores</strong>, habitualmente dois, situam-se posteriormente ao buraco palatino maior e atravessam a apófise piramidal do palatino, encaixada entre as extremidades inferiores das lâminas pterigóideas medial e lateral. O palato é ainda perfurado por numerosos pequenos buracos e apresenta depressões para as glândulas palatinas.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-118-answer','quiz-neuro-ap1-118','Buracos palatinos menores',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-118-incorrect','quiz-neuro-ap1-118','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-119',unit_id,'quiz-topic-neuro-ap1','Que estrutura projeta posteriormente o bordo do palato duro na linha média?',NULL,'Cristas palatinas de desenvolvimento variável projetam-se medialmente a partir da região posterior aos buracos palatinos maiores. O bordo posterior projeta-se como <strong>espinha nasal posterior</strong>. No adulto, a arcada alveolar apresenta normalmente até 16 alvéolos dentários, de dimensões e profundidades variáveis; consoante a morfologia das raízes, alguns são únicos e outros subdivididos por septos.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-119-answer','quiz-neuro-ap1-119','Espinha nasal posterior',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-119-incorrect','quiz-neuro-ap1-119','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-120',unit_id,'quiz-topic-neuro-ap1','Que osso forma superiormente o septo nasal ósseo?',NULL,'As fossas nasais situam-se acima do palato duro e são separadas na linha média pelo septo nasal. O septo nasal ósseo é formado superiormente pela lâmina perpendicular do <strong>etmóide</strong> e inferiormente pelo vómer. O bordo superior do vómer aproxima-se da face inferior do corpo do esfenóide, onde se expande numa asa de cada lado.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-120-answer','quiz-neuro-ap1-120','Etmóide',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-120-incorrect','quiz-neuro-ap1-120','Resposta não correspondente',2,0);
