INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-123',unit_id,'quiz-topic-neuro-ap1','Que estrutura separa posteriormente as duas coanas?',NULL,'O bordo superior do <strong>vómer</strong> aproxima-se da face inferior do corpo do esfenóide, onde se expande numa asa de cada lado. As duas aberturas nasais posteriores ou coanas encontram-se na extremidade posterior das fossas nasais e são separadas pelo bordo posterior livre do vómer. São limitadas inferiormente pelo bordo posterior das lâminas horizontais dos palatinos, superiormente pelo esfenóide e lateralmente pelas lâminas mediais das apófises pterigóides.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
