INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-126-incorrect','quiz-neuro-ap1-126','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-127',unit_id,'quiz-topic-neuro-ap1','Que estrutura óssea extracraniana corresponde internamente ao clivus?',NULL,'<strong>No adulto, o corpo do esfenóide funde-se com a parte basilar do occipital através da sincondrose esfeno-occipital, formando uma barra óssea mediana que se estende posteriormente até ao buraco magno e que, na face interna, corresponde ao clivus.</strong> O basioccipital apresenta um pequeno tubérculo faríngeo na linha média, que dá inserção ao rafe faríngeo e corresponde ao ponto mais superior de inserção do constritor superior da faringe.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-127-answer','quiz-neuro-ap1-127','Barra esfeno-occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-127-incorrect','quiz-neuro-ap1-127','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-128',unit_id,'quiz-topic-neuro-ap1','Que pequeno acidente mediano do basioccipital dá inserção ao rafe faríngeo?',NULL,'No adulto, o corpo do esfenóide funde-se com a parte basilar do occipital através da sincondrose esfeno-occipital, formando uma barra óssea mediana que se estende posteriormente até ao buraco magno e que, na face interna, corresponde ao clivus. O basioccipital apresenta um pequeno <strong>tubérculo faríngeo</strong> na linha média, que dá inserção ao rafe faríngeo e corresponde ao ponto mais superior de inserção do constritor superior da faringe. As porções petrosas dos temporais projetam-se a partir das regiões laterais da base e preenchem o espaço triangular entre a asa maior do esfenóide anteriormente e os bordos laterais do basioccipital posteriormente.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-128-answer','quiz-neuro-ap1-128','Tubérculo faríngeo',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-128-incorrect','quiz-neuro-ap1-128','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-129',unit_id,'quiz-topic-neuro-ap1','Que abertura resulta da lacuna entre ápice petroso e sincondrose esfeno-occipital?',NULL,'Entre a porção petrosa e a face infratemporal da asa maior do esfenóide encontram-se a junção petroesfenoidal e o sulco para a tuba faringotimpânica. O ápice da porção petrosa não alcança a sincondrose esfenooccipital; a lacuna assim criada corresponde ao <strong>buraco lácero</strong>. As apófises pterigóides descem da junção entre o corpo e a asa maior do esfenóide, ficando as lâminas medial e lateral separadas pela fossa pterigóidea.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-129-answer','quiz-neuro-ap1-129','Buraco lácero',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-129-incorrect','quiz-neuro-ap1-129','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-130',unit_id,'quiz-topic-neuro-ap1','Que estrutura separa as lâminas pterigóideas medial e lateral?',NULL,'O ápice da porção petrosa não alcança a sincondrose esfenooccipital; a lacuna assim criada corresponde ao buraco lácero. As apófises pterigóides descem da junção entre o corpo e a asa maior do esfenóide, ficando as lâminas medial e lateral separadas pela <strong>fossa pterigóidea</strong>. Anteriormente, as lâminas estão fundidas, exceto inferiormente, onde são separadas pela apófise piramidal do palatino; em crânios jovens as suturas nesta região podem ser visíveis.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-130-answer','quiz-neuro-ap1-130','Fossa pterigóidea',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-130-incorrect','quiz-neuro-ap1-130','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-131',unit_id,'quiz-topic-neuro-ap1','Que pequeno buraco variável pode existir entre o buraco oval e a fossa escafóide?',NULL,'O buraco oval e o buraco espinhoso podem confluir, e o bordo posterior do buraco espinhoso pode ser incompleto. Pode também existir um pequeno <strong>buraco emissário esfenoidal</strong> ou de Vesálio entre o buraco oval e a fossa escafóide; quando presente, transmite uma veia emissária entre o plexo pterigóideo e o seio cavernoso. O buraco lácero é limitado anteriormente pelo corpo do esfenóide, raízes adjacentes da apófise pterigóide e asa maior do esfenóide; posterolateralmente, pelo ápice da porção petrosa do temporal; e medialmente, pela parte basilar do occipital.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-131-answer','quiz-neuro-ap1-131','Buraco emissário esfenoidal',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-131-incorrect','quiz-neuro-ap1-131','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-132',unit_id,'quiz-topic-neuro-ap1','Que comunicação venosa atravessa o buraco emissário esfenoidal?',NULL,'O buraco oval e o buraco espinhoso podem confluir, e o bordo posterior do buraco espinhoso pode ser incompleto. <strong>Pode também existir um pequeno buraco emissário esfenoidal ou de Vesálio entre o buraco oval e a fossa escafóide; quando presente, transmite uma veia emissária entre o plexo pterigóideo e o seio cavernoso.</strong> O buraco lácero é limitado anteriormente pelo corpo do esfenóide, raízes adjacentes da apófise pterigóide e asa maior do esfenóide; posterolateralmente, pelo ápice da porção petrosa do temporal; e medialmente, pela parte basilar do occipital.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
