INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-132-incorrect','quiz-neuro-ap1-132','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-133',unit_id,'quiz-topic-neuro-ap1','Que grande estrutura atravessa integralmente o buraco lácero?',NULL,'O buraco lácero é limitado anteriormente pelo corpo do esfenóide, raízes adjacentes da apófise pterigóide e asa maior do esfenóide; posterolateralmente, pelo ápice da porção petrosa do temporal; e medialmente, pela parte basilar do occipital. Embora tenha quase 1 cm de extensão, não é atravessado integralmente por <strong>nenhuma</strong> estrutura de grande calibre. O canal carotídeo, quase circular, situa-se posterior e posterolateralmente ao buraco lácero na porção petrosa do temporal.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-133-answer','quiz-neuro-ap1-133','Nenhuma',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-133-incorrect','quiz-neuro-ap1-133','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-134',unit_id,'quiz-topic-neuro-ap1','Que artéria passa pela região superior do buraco lácero?',NULL,'O canal carotídeo, quase circular, situa-se posterior e posterolateralmente ao buraco lácero na porção petrosa do temporal. A <strong>artéria carótida interna</strong> entra na base do crânio pela abertura externa do canal carotídeo, ascende no canal e curva-se anteromedialmente até à parede posterior do buraco lácero. Depois ascende pela sua extremidade superior, acompanhada por plexos venosos e simpáticos.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-134-answer','quiz-neuro-ap1-134','Artéria carótida interna',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-134-incorrect','quiz-neuro-ap1-134','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-135',unit_id,'quiz-topic-neuro-ap1','Que canal se situa posterolateralmente ao buraco lácero?',NULL,'Embora tenha quase 1 cm de extensão, não é atravessado integralmente por nenhuma estrutura de grande calibre. O <strong>canal carotídeo</strong>, quase circular, situa-se posterior e posterolateralmente ao buraco lácero na porção petrosa do temporal. A artéria carótida interna entra na base do crânio pela abertura externa do canal carotídeo, ascende no canal e curva-se anteromedialmente até à parede posterior do buraco lácero.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-135-answer','quiz-neuro-ap1-135','Canal carotídeo',1,1);
