INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-136',unit_id,'quiz-topic-neuro-ap1','Que canal nasce junto do bordo anterior do buraco lácero e segue para a fossa pterigopalatina?',NULL,'Em vida, a porção inferior encontra-se parcialmente preenchida por restos cartilagíneos do condrocrânio embrionário. O <strong>canal pterigóideo</strong> observa-se na base do crânio junto ao bordo anterior do buraco lácero, superiormente e entre as lâminas pterigóideas do esfenóide. Dirige-se para a fossa pterigopalatina e transmite o nervo do canal pterigóideo e vasos acompanhantes.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-136-answer','quiz-neuro-ap1-136','Canal pterigóideo',1,1);
