INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-137',unit_id,'quiz-topic-neuro-ap1','Que estrutura nervosa atravessa o buraco magno em sentido ascendente para o crânio?',NULL,'Contém a extremidade inferior do bulbo, meninges, líquido cefalorraquidiano, artérias e veias vertebrais e <strong>raízes do nervo acessório</strong>; o ligamento apical do dente e a membrana tectória atravessam-no para se fixarem internamente no basioccipital. Anteriormente, o bordo do buraco magno é parcialmente sobreposto pelos côndilos occipitais, que se projetam inferiormente para articular com as facetas articulares superiores das massas laterais do atlas.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
