INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-138-incorrect','quiz-neuro-ap1-138','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-139',unit_id,'quiz-topic-neuro-ap1','Que parte do sistema nervoso atravessa inferiormente o buraco magno?',NULL,'A fossa craniana posterior é formada pelos ossos esfenóide, temporais e occipital e contém o cerebelo, a ponte e o bulbo raquidiano. O buraco magno é o acidente mais proeminente do pavimento desta fossa. O <strong>bulbo raquidiano atravessa o buraco magno em sentido inferior</strong>, saindo da cavidade craniana para se continuar como medula espinhal.<p><small>Gray’s Anatomy, 42.ª ed., p. 567.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-139-answer','quiz-neuro-ap1-139','Bulbo raquidiano',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-139-incorrect','quiz-neuro-ap1-139','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-140',unit_id,'quiz-topic-neuro-ap1','Que articulação formam os côndilos occipitais?',NULL,'A articulação entre o crânio e a coluna vertebral inclui os côndilos occipitais, o atlas e o áxis. Nas <strong>articulações atlanto-occipitais</strong>, o atlas articula-se com o occipital por um par de articulações sinoviais. Cada articulação possui duas superfícies reciprocamente curvas: uma no côndilo occipital e outra na massa lateral do atlas.<p><small>Gray’s Anatomy, 42.ª ed., cap. 46, pp. 839–840.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-140-answer','quiz-neuro-ap1-140','Articulação atlanto-occipital',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-140-incorrect','quiz-neuro-ap1-140','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-141',unit_id,'quiz-topic-neuro-ap1','Que canal atravessa profundamente o côndilo occipital?',NULL,'É fortemente convexo no sentido anteroposterior e menos no sentido transversal; a face medial é rugosa devido a inserções ligamentares. O <strong>canal do nervo hipoglosso</strong> dirige-se lateralmente e ligeiramente anteriormente, atravessa profundamente cada côndilo e transmite o nervo hipoglosso, um ramo meníngeo da artéria faríngea ascendente e uma veia emissária do plexo basilar. Imediatamente atrás do côndilo existe a fossa condilar, que pode conter um canal condilar posterior para uma veia emissária do seio sigmóide.<p><small>Gray’s Anatomy, 42.ª ed., p. 564.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-141-answer','quiz-neuro-ap1-141','Canal do nervo hipoglosso',1,1);
