INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-147',unit_id,'quiz-topic-neuro-ap1','Que vaso emerge posteriormente pelo buraco jugular?',NULL,'O buraco jugular é um hiato grande, assimétrico e irregular situado na extremidade posterior da junção petro-occipital, entre a apófise jugular do occipital e a fossa jugular da porção petrosa do temporal. Através dele passam o seio petroso inferior, anteriormente, os nervos glossofaríngeo, vago e acessório, na porção média, e a <strong>veia jugular interna</strong>, posteriormente. Um canalículo mastoideu atravessa a parede lateral da fossa jugular e transmite o ramo auricular do vago.<p><small>Gray’s Anatomy, 42.ª ed., pp. 564–565.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-147-answer','quiz-neuro-ap1-147','Veia jugular interna',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-147-incorrect','quiz-neuro-ap1-147','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-148',unit_id,'quiz-topic-neuro-ap1','Que canalículo transmite o ramo auricular do vago?',NULL,'Através dele passam o seio petroso inferior, anteriormente, os nervos glossofaríngeo, vago e acessório, na porção média, e a veia jugular interna, posteriormente. Um <strong>canalículo mastoideu</strong> atravessa a parede lateral da fossa jugular e transmite o ramo auricular do vago. O canalículo para o ramo timpânico do glossofaríngeo situa-se na crista entre a fossa jugular e a abertura do canal carotídeo.<p><small>Gray’s Anatomy, 42.ª ed., pp. 564–565.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-148-answer','quiz-neuro-ap1-148','Canalículo mastoideu',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-148-incorrect','quiz-neuro-ap1-148','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-149',unit_id,'quiz-topic-neuro-ap1','Que canalículo transmite o ramo timpânico do glossofaríngeo?',NULL,'Um canalículo mastoideu atravessa a parede lateral da fossa jugular e transmite o ramo auricular do vago. <strong>O canalículo para o ramo timpânico do glossofaríngeo situa-se na crista entre a fossa jugular e a abertura do canal carotídeo.</strong> Medialmente no limite superior do buraco pode existir uma pequena incisura relacionada com o gânglio inferior do glossofaríngeo; no ápice desta incisura pode observar-se a abertura do canalículo coclear.<p><small>Gray’s Anatomy, 42.ª ed., pp. 564–565.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-149-answer','quiz-neuro-ap1-149','Canalículo timpânico',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-149-incorrect','quiz-neuro-ap1-149','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-150',unit_id,'quiz-topic-neuro-ap1','Que fissura transmite a corda do tímpano para a fossa infratemporal?',NULL,'A corda do tímpano entra na cavidade timpânica pelo canalículo posterior, atravessa a cavidade e abandona-a pelo canalículo anterior. Este canalículo abre-se na extremidade medial da <strong>fissura petrotimpânica</strong>, por onde a corda do tímpano alcança a fossa infratemporal.<p><small>Gray’s Anatomy, 42.ª ed., cap. 42, p. 743.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-150-answer','quiz-neuro-ap1-150','Fissura petrotimpânica',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-150-incorrect','quiz-neuro-ap1-150','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-151',unit_id,'quiz-topic-neuro-ap1','Que buraco transmite o nervo facial na base externa do crânio?',NULL,'A lâmina timpânica forma o pavimento do meato acústico externo. O <strong>buraco estilomastoideu</strong> situa-se entre as apófises mastoideia e estilóide na face lateral do temporal e transmite o nervo facial e a artéria estilomastoideia. A distância entre a apófise estilóide e o buraco estilomastoideu diminui com a idade (Krmpotić Nemanić et al., 2009).<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-151-answer','quiz-neuro-ap1-151','Buraco estilomastoideu',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-151-incorrect','quiz-neuro-ap1-151','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-152',unit_id,'quiz-topic-neuro-ap1','Que artéria acompanha o nervo facial no buraco estilomastoideu?',NULL,'A lâmina timpânica forma o pavimento do meato acústico externo. O buraco estilomastoideu situa-se entre as apófises mastoideia e estilóide na face lateral do temporal e transmite o nervo facial e a <strong>artéria estilomastoideia</strong>. A distância entre a apófise estilóide e o buraco estilomastoideu diminui com a idade (Krmpotić Nemanić et al., 2009).<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-152-answer','quiz-neuro-ap1-152','Artéria estilomastoideia',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-152-incorrect','quiz-neuro-ap1-152','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-153',unit_id,'quiz-topic-neuro-ap1','Que músculo se origina na incisura mastoideia?',NULL,'A distância entre a apófise estilóide e o buraco estilomastoideu diminui com a idade (Krmpotić Nemanić et al., 2009). Medialmente à apófise mastoideia existe a incisura mastoideia, onde se origina o <strong>ventre posterior do digástrico</strong>; ainda mais medialmente pode existir um sulco para a artéria occipital. Um buraco mastoideu pode surgir próximo ou no interior da sutura occipitomastoideia e, quando presente, transmite uma veia emissária do seio sigmóide.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-153-answer','quiz-neuro-ap1-153','Ventre posterior do digástrico',1,1);
